function _rng(seed){ var s=seed>>>0||1; return function(){ s=(s*1664525+1013904223)>>>0; return s/4294967296; }; }
function kmGenBlobs(n, k, rnd, spread){
  var centers=[]; for(var i=0;i<k;i++) centers.push([rnd(), rnd()]);
  var pts=[]; for(var i=0;i<n;i++){ var c=centers[Math.floor(rnd()*k)];
    pts.push([c[0]+(rnd()-0.5)*spread, c[1]+(rnd()-0.5)*spread]); }
  return pts;
}
function kmDist(a,b){ var dx=a[0]-b[0], dy=a[1]-b[1]; return dx*dx+dy*dy; }
function kmAssign(pts, cents){
  var lab=[]; for(var i=0;i<pts.length;i++){ var best=0,bd=Infinity;
    for(var j=0;j<cents.length;j++){ var d=kmDist(pts[i],cents[j]); if(d<bd){bd=d;best=j;} } lab.push(best); }
  return lab;
}
function kmUpdate(pts, lab, k, prev){
  var sx=[],sy=[],n=[]; for(var j=0;j<k;j++){sx.push(0);sy.push(0);n.push(0);}
  for(var i=0;i<pts.length;i++){ var c=lab[i]; sx[c]+=pts[i][0]; sy[c]+=pts[i][1]; n[c]++; }
  var cents=[]; for(var j=0;j<k;j++){ if(n[j]>0) cents.push([sx[j]/n[j], sy[j]/n[j]]); else cents.push(prev[j]?prev[j].slice():[0.5,0.5]); }
  return cents;
}
function kmInertia(pts, lab, cents){ var s=0; for(var i=0;i<pts.length;i++){ s+=kmDist(pts[i], cents[lab[i]]); } return s; }
function kmInitCentroids(pts,k,rnd){
  var idx=[]; var first=Math.floor(rnd()*pts.length); idx.push(first);
  while(idx.length<k){ var cand=Math.floor(rnd()*pts.length); if(idx.indexOf(cand)<0) idx.push(cand); }
  return idx.map(function(i){return pts[i].slice();});
}
var EXPORTS={kmGenBlobs:kmGenBlobs, kmDist:kmDist, kmAssign:kmAssign, kmUpdate:kmUpdate, kmInertia:kmInertia, kmInitCentroids:kmInitCentroids, _rng:_rng};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.KMeansForgePure = EXPORTS; }
